/// Raven `Do_Strike`.
///
/// lightning strike trigger lightning strike event
/// Source: `oracle/oracle/codemp/game/g_trigger.c:739-786`
pub fn Do_Strike(
    ctx: GameContext<'_>,ent: *mut gentity_t) {
    unsafe {
        // maybe allow custom fx direction at some point?
        let fx_ang: vec3_t = [90.0, 0.0, 0.0];

        // choose a random point to strike within the bounds of the trigger
        let mut strike_point: vec3_t = [0.0; 3];
        strike_point[0] = flrand((*ent).r.absmin[0], (*ent).r.absmax[0]);
        strike_point[1] = flrand((*ent).r.absmin[1], (*ent).r.absmax[1]);
        // consider the bottom mins the ground level
        strike_point[2] = (*ent).r.absmin[2];

        // set the from point
        let mut strike_from: vec3_t = [
            strike_point[0],
            strike_point[1],
            (*ent).r.absmax[2] - 4.0,
        ];

        // now trace for damaging stuff, and do the effect
        // Raven's `NULL` mins/maxs (point trace) — `zero` stands in since the
        // resolved `GTraceArgs` takes `*const vec3_t`, not an optional.
        let zero: vec3_t = [0.0; 3];
        let mut local_trace: trace_t = core::mem::zeroed();
        trap::Trace(
            ctx.engine,
            GTraceArgs::new(
                &mut local_trace as *mut trace_t,
                &strike_from as *const vec3_t,
                &zero as *const vec3_t,
                &zero as *const vec3_t,
                &strike_point as *const vec3_t,
                (*ent).s.number,
                MASK_PLAYERSOLID,
            ),
        );
        strike_point = local_trace.endpos;

        if local_trace.startsolid != 0 || local_trace.allsolid != 0 {
            // got a bad spot, think again next frame to try another strike
            (*ent).nextthink = (*ctx.world).level.time;
            return;
        }

        if (*ent).radius != 0.0 {
            // do a radius damage at the end pos
            G_RadiusDamage(
                ctx,
                strike_point,
                ent,
                (*ent).damage as f32,
                (*ent).radius,
                ent,
                core::ptr::null_mut(),
                MOD_SUICIDE as c_int,
            );
        } else {
            // only damage individuals
            let tr_hit = &mut (*ctx.world).entities[local_trace.entityNum as usize] as *mut gentity_t;

            if (*tr_hit).inuse != 0 && (*tr_hit).takedamage != 0 {
                // damage it then
                G_Damage(
                    tr_hit,
                    ent,
                    ent,
                    vec3_origin,
                    (*tr_hit).r.currentOrigin,
                    (*ent).damage,
                    0,
                    MOD_SUICIDE as c_int,
                );
            }
        }

        G_PlayEffectID((*ent).genericValue2, strike_from, fx_ang);
    }
}

/// Raven `Think_Strike`.
///
/// lightning strike trigger think loop
/// Source: `oracle/oracle/codemp/game/g_trigger.c:789-798`
pub fn Think_Strike(
    ctx: GameContext<'_>,ent: *mut gentity_t) {
    unsafe {
        if (*ent).genericValue1 != 0 {
            // turned off currently
            return;
        }

        (*ent).nextthink =
            (*ctx.world).level.time + (*ent).wait as c_int + Q_irand(0, (*ent).random as c_int);
        Do_Strike(ctx, ent);
    }
}

/// Raven `Use_Strike`.
///
/// lightning strike trigger use event function
/// Source: `oracle/oracle/codemp/game/g_trigger.c:801-809`
pub fn Use_Strike(
    ctx: GameContext<'_>,ent: *mut gentity_t, other: *mut gentity_t, activator: *mut gentity_t) {
    unsafe {
        (*ent).genericValue1 = (((*ent).genericValue1 == 0) as c_int);

        if (*ent).genericValue1 == 0 {
            // turn it back on
            (*ent).nextthink = (*ctx.world).level.time;
        }
    }
}

/// Raven `SP_trigger_lightningstrike`.
///
/// Source: `oracle/oracle/codemp/game/g_trigger.c:824-861`
pub fn SP_trigger_lightningstrike(
    ctx: GameContext<'_>,ent: *mut gentity_t) {
    unsafe {
        (*ent).use_ = Some(EntUse::Use_Strike);
        (*ent).think = Some(EntThink::Think_Strike);
        (*ent).nextthink = (*ctx.world).level.time + 500;

        let mut s: *mut c_char = core::ptr::null_mut();
        G_SpawnString(ctx, c"lightningfx".as_ptr(), c"".as_ptr(), &mut s as *mut *mut c_char);
        if s.is_null() || *s == 0 {
            // Com_Error(ERR_DROP, ...) -> panic (frozen Group A).
            panic!("trigger_lightningstrike with no lightningfx");
        }

        // get a configstring index for it
        (*ent).genericValue2 = G_EffectIndex(s);

        if (*ent).spawnflags & 1 != 0 {
            // START_OFF
            (*ent).genericValue1 = 1;
        }

        if (*ent).wait == 0.0 {
            // default 1000
            (*ent).wait = 1000.0;
        }
        if (*ent).random == 0.0 {
            // default 2000
            (*ent).random = 2000.0;
        }
        if (*ent).damage == 0 {
            // default 50
            (*ent).damage = 50;
        }

        InitTrigger(ctx, ent);
        trap::LinkEntity(ctx.engine, GLinkentityArgs::new(ent));
    }
}

