/// Raven `Use_target_push`.
///
/// Source: `oracle/oracle/codemp/game/g_trigger.c:1138-1159`
pub fn Use_target_push(
    ctx: GameContext<'_>,self_: *mut gentity_t, other: *mut gentity_t, activator: *mut gentity_t) {
    unsafe {
        if (*activator).client.is_null() {
            return;
        }

        let client = (*activator).client as *mut gclient_t;
        if (*client).ps.pm_type != PM_NORMAL as c_int && (*client).ps.pm_type != PM_FLOAT as c_int
        {
            return;
        }

        G_ActivateBehavior(ctx, self_, BSET_USE);

        (*client).ps.velocity = (*self_).s.origin2;

        // play fly sound every 1.5 seconds
        if (*activator).fly_sound_debounce_time < (*ctx.world).level.time {
            (*activator).fly_sound_debounce_time = (*ctx.world).level.time + 1500;
            if (*self_).noise_index != 0 {
                G_Sound(ctx, activator, CHAN_AUTO, (*self_).noise_index);
            }
        }
    }
}

/// Raven `SP_target_push`.
///
/// CONSTANT will push activator in direction of 'target' at constant 'speed'
/// Source: `oracle/oracle/codemp/game/g_trigger.c:1168-1187`
pub fn SP_target_push(
    ctx: GameContext<'_>,self_: *mut gentity_t) {
    unsafe {
        if (*self_).speed == 0.0 {
            (*self_).speed = 1000.0;
        }
        // Cross-file `G_SetMovedir` resolves to a by-value/void signature (no
        // out-param channel yet — fork-9 reshape is that shard's job); call
        // as given, `s.origin2` written faithfully once that lands.
        G_SetMovedir((*self_).s.angles, (*self_).s.origin2);
        (*self_).s.origin2 = [
            (*self_).s.origin2[0] * (*self_).speed,
            (*self_).s.origin2[1] * (*self_).speed,
            (*self_).s.origin2[2] * (*self_).speed,
        ];

        if (*self_).spawnflags & 1 != 0 {
            (*self_).noise_index = G_SoundIndex(c"sound/weapons/force/jump.wav".as_ptr());
        } else {
            // G_SoundIndex("sound/misc/windfly.wav");
            (*self_).noise_index = 0;
        }
        if !(*self_).target.is_null() {
            (*self_).r.absmin = (*self_).s.origin;
            (*self_).r.absmax = (*self_).s.origin;
            (*self_).think = Some(EntThink::AimAtTarget);
            (*self_).nextthink = (*ctx.world).level.time + FRAMETIME;
        }
        (*self_).use_ = Some(EntUse::Use_target_push);
    }
}

/// Raven `trigger_teleporter_touch`.
///
/// Source: `oracle/oracle/codemp/game/g_trigger.c:1197-1225`
pub fn trigger_teleporter_touch(
    ctx: GameContext<'_>,self_: *mut gentity_t, other: *mut gentity_t, trace: *mut trace_t) {
    unsafe {
        if (*self_).flags & FL_INACTIVE != 0 {
            // set by target_deactivate
            return;
        }

        if (*other).client.is_null() {
            return;
        }
        // TODO: Port PM_DEAD / ps.pm_type check — playerState_t.pm_type field
        // access needs the typed `gclient_t` this staged `client: *mut c_void`
        // does not carry.
        // Source: oracle/oracle/codemp/game/g_trigger.c:1208-1215

        let dest = G_PickTarget(ctx, (*self_).target);
        if dest.is_null() {
            G_Printf(ctx, b"Couldn't find teleporter destination\n\0".as_ptr() as *const c_char);
            return;
        }

        TeleportPlayer(ctx, other, (*dest).s.origin, (*dest).s.angles);
    }
}

