/// Raven `hurt_use`.
///
/// Source: `oracle/oracle/codemp/game/g_trigger.c:1280-1297`
pub fn hurt_use(
    ctx: GameContext<'_>,self_: *mut gentity_t, other: *mut gentity_t, activator: *mut gentity_t) {
    unsafe {
        if !activator.is_null() && (*activator).inuse != 0 && !(*activator).client.is_null() {
            (*self_).activator = activator;
        } else {
            (*self_).activator = None;
        }

        G_ActivateBehavior(ctx, self_, BSET_USE);

        if (*self_).r.linked != 0 {
            trap::UnlinkEntity(ctx.engine, GUnlinkentityArgs::new(self_));
        } else {
            trap::LinkEntity(ctx.engine, GLinkentityArgs::new(self_));
        }
    }
}

