/// Raven `asteroid_pick_random_asteroid`.
///
/// Source: `oracle/oracle/codemp/game/g_trigger.c:1798-1841`
pub fn asteroid_pick_random_asteroid(
    ctx: GameContext<'_>,self_: *mut gentity_t) -> *mut gentity_t {
    unsafe {
        let mut t_count: c_int = 0;
        let mut t: *mut gentity_t = core::ptr::null_mut();

        loop {
            t = G_Find(
                ctx,
                t,
                core::mem::offset_of!(gentity_t, targetname) as c_int,
                (*self_).target,
            );
            if t.is_null() {
                break;
            }
            if t != self_ {
                t_count += 1;
            }
        }

        if t_count == 0 {
            return core::ptr::null_mut();
        }

        if t_count == 1 {
            return G_Find(
                ctx,
                core::ptr::null_mut(),
                core::mem::offset_of!(gentity_t, targetname) as c_int,
                (*self_).target,
            );
        }

        // FIXME: need a seed
        let pick = Q_irand(1, t_count);
        t_count = 0;
        t = core::ptr::null_mut();
        loop {
            t = G_Find(
                ctx,
                t,
                core::mem::offset_of!(gentity_t, targetname) as c_int,
                (*self_).target,
            );
            if t.is_null() {
                break;
            }
            if t != self_ {
                t_count += 1;
            } else {
                continue;
            }

            if t_count == pick {
                return t;
            }
        }
        core::ptr::null_mut()
    }
}

/// Raven `asteroid_count_num_asteroids`.
///
/// Source: `oracle/oracle/codemp/game/g_trigger.c:1843-1859`
pub fn asteroid_count_num_asteroids(
    ctx: GameContext<'_>,self_: *mut gentity_t) -> c_int {
    unsafe {
        let mut count: c_int = 0;
        let mut i = MAX_CLIENTS as c_int;
        while i < ENTITYNUM_WORLD as c_int {
            if (*ctx.world).entities[i as usize].inuse == 0 {
                i += 1;
                continue;
            }
            if (*ctx.world).entities[i as usize].r.ownerNum == (*self_).s.number {
                count += 1;
            }
            i += 1;
        }
        count
    }
}

/// Raven `asteroid_move_to_start2`.
///
/// move asteroid to a new start position
/// Source: `oracle/oracle/codemp/game/g_trigger.c:1864-1920`
pub fn asteroid_move_to_start2(
    ctx: GameContext<'_>,self_: *mut gentity_t, ownerTrigger: *mut gentity_t) {
    unsafe {
        if !ownerTrigger.is_null() {
            // move it
            let speed = flrand((*self_).speed * 0.25, (*self_).speed * 2.0);
            let cap_axis = Q_irand(0, 2);

            let mut start_spot: vec3_t = [0.0; 3];
            let mut end_spot: vec3_t = [0.0; 3];

            for axis in 0..3usize {
                if axis as c_int == cap_axis {
                    if Q_irand(0, 1) != 0 {
                        start_spot[axis] = (*ownerTrigger).r.mins[axis];
                        end_spot[axis] = (*ownerTrigger).r.maxs[axis];
                    } else {
                        start_spot[axis] = (*ownerTrigger).r.maxs[axis];
                        end_spot[axis] = (*ownerTrigger).r.mins[axis];
                    }
                } else {
                    start_spot[axis] = (*ownerTrigger).r.mins[axis]
                        + (flrand(0.0, 1.0) * ((*ownerTrigger).r.maxs[axis] - (*ownerTrigger).r.mins[axis]));
                    end_spot[axis] = (*ownerTrigger).r.mins[axis]
                        + (flrand(0.0, 1.0) * ((*ownerTrigger).r.maxs[axis] - (*ownerTrigger).r.mins[axis]));
                }
            }
            // FIXME: maybe trace from start to end to make sure nothing is in
            // the way? How big of a trace?

            G_SetOrigin(self_, start_spot);
            let dist = crate::q_math::Distance(end_spot, start_spot);
            let time = ((dist / speed).ceil() as c_int) * 1000;
            crate::g_ICARUScb::Q3_Lerp2Origin(ctx, -1, (*self_).s.number, end_spot, time as f32);

            // spin it
            let start_angles: vec3_t = [
                flrand(-360.0, 360.0),
                flrand(-360.0, 360.0),
                flrand(-360.0, 360.0),
            ];
            G_SetAngles(self_, start_angles);
            (*self_).s.apos.trDelta = [flrand(-100.0, 100.0), flrand(-100.0, 100.0), flrand(-100.0, 100.0)];
            (*self_).s.apos.trTime = (*ctx.world).level.time;
            (*self_).s.apos.trType = TR_LINEAR;
            // move it back to a new start when done
            (*self_).think = Some(EntThink::asteroid_move_to_start);
            (*self_).nextthink = (*ctx.world).level.time + time;
        } else {
            // crap, go bye-bye
            (*self_).think = Some(EntThink::G_FreeEntity);
            (*self_).nextthink = (*ctx.world).level.time + FRAMETIME;
        }
    }
}

/// Raven `asteroid_move_to_start`.
///
/// move asteroid to a new start position
/// Source: `oracle/oracle/codemp/game/g_trigger.c:1922-1925`
pub fn asteroid_move_to_start(
    ctx: GameContext<'_>,self_: *mut gentity_t) {
    unsafe {
        let owner_trigger =
            &mut (*ctx.world).entities[(*self_).r.ownerNum as usize] as *mut gentity_t;
        asteroid_move_to_start2(ctx, self_, owner_trigger);
    }
}

/// Raven `asteroid_field_think`.
///
/// Source: `oracle/oracle/codemp/game/g_trigger.c:1927-1979`
pub fn asteroid_field_think(
    ctx: GameContext<'_>,self_: *mut gentity_t) {
    unsafe {
        let num_asteroids = asteroid_count_num_asteroids(ctx, self_);

        (*self_).nextthink = (*ctx.world).level.time + 500;

        if num_asteroids < (*self_).count {
            // need to spawn a new asteroid
            let new_asteroid = G_Spawn(ctx);
            if !new_asteroid.is_null() {
                let copy_asteroid = asteroid_pick_random_asteroid(ctx, self_);
                if !copy_asteroid.is_null() {
                    (*new_asteroid).model = (*copy_asteroid).model;
                    (*new_asteroid).model2 = (*copy_asteroid).model2;
                    (*new_asteroid).health = (*copy_asteroid).health;
                    (*new_asteroid).spawnflags = (*copy_asteroid).spawnflags;
                    (*new_asteroid).mass = (*copy_asteroid).mass;
                    (*new_asteroid).damage = (*copy_asteroid).damage;
                    (*new_asteroid).speed = (*copy_asteroid).speed;

                    G_SetOrigin(new_asteroid, (*copy_asteroid).s.origin);
                    G_SetAngles(new_asteroid, (*copy_asteroid).s.angles);
                    (*new_asteroid).classname = c"func_rotating".as_ptr() as *mut c_char;

                    SP_func_rotating(ctx, new_asteroid);

                    (*new_asteroid).genericValue15 = (*copy_asteroid).genericValue15;
                    (*new_asteroid).s.iModelScale = (*copy_asteroid).s.iModelScale;
                    (*new_asteroid).maxHealth = (*new_asteroid).health;
                    G_ScaleNetHealth(new_asteroid);
                    (*new_asteroid).radius = (*copy_asteroid).radius;
                    (*new_asteroid).material = (*copy_asteroid).material;
                    // CacheChunkEffects( self->material );

                    // keep track of it
                    (*new_asteroid).r.ownerNum = (*self_).s.number;

                    // position it
                    asteroid_move_to_start2(ctx, new_asteroid, self_);

                    // think again sooner if need even more
                    if num_asteroids + 1 < (*self_).count {
                        // still need at least one more — spawn it in 100ms
                        (*self_).nextthink = (*ctx.world).level.time + 100;
                    }
                }
            }
        }
    }
}

